import{_ as r,o as i,c as s,a3 as t,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/suchen-gruppenprozesse/schueler-suchen.png",S=JSON.parse('{"title":"Eine Schülerin oder einen Schüler suchen","description":"","frontmatter":{"title":"Eine Schülerin oder einen Schüler suchen","source_pageid":565,"source_revision":3357},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/schuelersuche-schueler.md","filePath":"schild3/suchen-gruppenprozesse/schuelersuche-schueler.md"}'),h={name:"schild3/suchen-gruppenprozesse/schuelersuche-schueler.md"};function c(u,n,o,d,m,g){return i(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="eine-schulerin-oder-einen-schuler-suchen" tabindex="-1">Eine Schülerin oder einen Schüler suchen <a class="header-anchor" href="#eine-schulerin-oder-einen-schuler-suchen" aria-label="Permalink to &quot;Eine Schülerin oder einen Schüler suchen&quot;">​</a></h1><p>Finden Sie Schülerdatensätze anhand von Namen, Anschrift, Geburtsdatum oder Statistiknummer. Die Suchoptionen steuern unter anderem Status und den Umgang mit gelöschten Datensätzen.</p><p><a href="/bilder/suchen-gruppenprozesse/schueler-suchen.png"><img src="'+l+'" alt="Schüler lassen sich schnell suchen." loading="lazy"></a></p><p><em>Schüler lassen sich schnell suchen.</em></p><h2 id="schulersuche" tabindex="-1">Schülersuche <a class="header-anchor" href="#schulersuche" aria-label="Permalink to &quot;Schülersuche&quot;">​</a></h2><p>Indem Sie in <em>Schüler</em> auf <strong>Suchen</strong> klicken, öffnet sich ein Fenster, über das sich Schüler sehr schnell finden lassen.</p><p>Geben Sie Kriterien wie <em>Name</em>, <em>Vorname</em>, die <em>Straße</em> oder das <em>Geburtsdatum</em> ein, um sofort alle Schüler angezeigt zu bekommen, auf die alle eingegebenen Kriterien zutreffen.</p><p>Haben Sie eine <em>Prüfung auf Statistikfehler</em> durchgeführt, lassen sich gefundene Schüler mit Fehlern gut über die Eingabe der im Fehlerprotokoll aufgeführten <em>Statistik-Nr.</em> finden.</p><p>Über Haken unterhalb des Suchfeldes lässt sich die Suche weiter eingrenzen.</p><ul><li><strong>Nur aktive Schüler suchen</strong> grenzt die Suche auf die nur aktiven Schüler ein. Per Standard werden alle Schüler in der Datenbank angezeigt.</li><li><strong>Groß- und Kleinschreibung</strong> wird in der Standardeinstellung ignoriert.</li><li><strong>Auch gelöschte Schüler zeigen</strong> blendet Schüler mit einem Löschvermerk wieder ein. Somit ließe sich der Löschvermerk auf wieder entfernen.</li><li><strong>Suche erst beim Drücken der Eingabe ausführen</strong> sorgt dafür, dass nicht nach jedem eingegebenen Zeichen die Suche sofort ausgeführt wird.</li></ul><p>Ein <strong>Doppelklick</strong> auf einen Schülereintrag im Suchfenster springt sofort auf den betreffenden Schüler im Schülercontainer, so dass nun mit diesem weitergearbeitet werden kann.</p><p>In der Kopfzeile des Suchfensters kann auf den Reiter <em>Nach Erziehernamen suchen</em> umgeschaltet werden. Somit lassen sich unter <em>Erz. Berechtigte</em> eingetragene Personen auffinden.</p><h2 id="videotutorial" tabindex="-1">Videotutorial <a class="header-anchor" href="#videotutorial" aria-label="Permalink to &quot;Videotutorial&quot;">​</a></h2>',13),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/vF1j_7-74hM?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sch%C3%BClersuche_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),a(" · Quellrevision 3357.")],-1)])])}const f=r(h,[["render",c]]);export{S as __pageData,f as default};
